  "total_results": 1,
  "papers": [
    {
      "id": "2312.07732v1",
      "title": "Estimation of Dynamic Origin-Destination Matrices in a Railway Transportation Network integrating Ticket Sales and Passenger Count Data",
      "authors": [
        "Greta Galliani",
        "Piercesare Secchi",
        "Francesca Ieva"
      ],
      "abstract": "Accurately estimating Origin-Destination (OD) matrices is a topic of\nincreasing interest for efficient transportation network management and\nsustainable urban planning. Traditionally, travel surveys have supported this\nprocess; however, their availability and comprehensiveness can be limited.\nMoreover, the recent COVID-19 pandemic has triggered unprecedented shifts in\nmobility patterns, underscoring the urgency of accurate and dynamic mobility\ndata supporting policies and decisions with data-driven evidence. In this\nstudy, we tackle these challenges by introducing an innovative pipeline for\nestimating dynamic OD matrices. The real motivating problem behind this is\nbased on the Trenord railway transportation network in Lombardy, Italy. We\napply a novel approach that integrates ticket and subscription sales data with\npassenger counts obtained from Automated Passenger Counting (APC) systems,\nmaking use of the Iterative Proportional Fitting (IPF) algorithm. Our work\neffectively addresses the complexities posed by incomplete and diverse data\nsources, showcasing the adaptability of our pipeline across various\ntransportation contexts. Ultimately, this research bridges the gap between\navailable data sources and the escalating need for precise OD matrices. The\nproposed pipeline fosters a comprehensive grasp of transportation network\ndynamics, providing a valuable tool for transportation operators, policymakers,\nand researchers. Indeed, to highlight the potentiality of dynamic OD matrices,\nwe showcase some methods to perform anomaly detection of mobility trends in the\nnetwork through such matrices and interpret them in light of events that\nhappened in the last months of 2022.",
      "categories": [
        "stat.AP",
        "62P30, 62-04, 62-08",
        "G.3"
      ],
      "published": "2023-12-12T20:56:26+00:00",
      "url": "http://arxiv.org/pdf/2312.07732v1",
      "resource_uri": "arxiv://2312.07732v1"
    }
  ]
}

